insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 1, 'When the engine will not accept an input, what does it hand back?', '["A full result in which the refused input is replaced by a figure the engine picks for itself, with a warning printed under the reason column so the learner can see which input was swapped.", "Figures of zero throughout, so that any calculation built on the bad input visibly adds up to nothing at all.", "An object carrying an error and the field it refused, with a message that starts with that field''s name and states the condition that failed.", "A blank panel with a generic error code, which the learner looks up in a table printed at the end of the course."]'::jsonb, 2, 'A refusal is an object with an error and a field, and its message begins with the field it names and says exactly which condition failed. The engine never substitutes a figure of its own for a refused input, it never returns a result of zeros in place of a refusal, and every message is printed in the engine''s own words in the panel, with no code to look up.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 2, 'Which four functions does the register calculator, the Associate tier''s panel, call?', '["criticality, abcClassification, eoq and slowMoving.", "criticality, abcClassification, eoq and quantityDiscount.", "eoq, slowMoving, safetyStock and poissonStock, for the stock targets.", "criticality and eoq only."]'::jsonb, 0, 'The register calculator calls criticality, abcClassification, eoq and slowMoving: the four questions of this tier. The price schedule and the stock targets belong to the Professional tier''s stock calculator. Every view of the register calculator runs in the course itself, and the Materials & Spares Planner gives the same figures on the same inputs.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 3, 'The course''s table of sources gives each text a date it was read. What is that date?', '["February 1913, the issue date of the trade magazine that printed the square-root lot size.", "1 October 1998, the date the reliability handbook the course quotes was issued.", "Fall 2006, the term in which the MIT logistics lectures were taught and published.", "2026-09-27, the same date for every text in the table, whatever its own edition."]'::jsonb, 3, 'Every text was read on 2026-09-27. February 1913 is the edition date of Harris''s article, 1 October 1998 is the date of MIL-HDBK-338B and Fall 2006 is the term of the ESD.260J lectures. Each of those is an edition or a date of the text itself, which the table gives beside the date it was read.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 4, 'C. Caplice''s MIT ESD.260J Logistics Systems lectures (Fall 2006) are cited by lecture and slide, and none of their sentences appears in the course. Why?', '["They were withdrawn by MIT in 2007, so only their slide numbers can still be checked by a reader today.", "They are licensed CC BY-NC-SA 4.0, which is non-commercial, and this course is sold.", "Each slide is too short to quote, so the course lists slide numbers only.", "Their figures are all slips, so the course points at them only to show where each printed figure went wrong."]'::jsonb, 1, 'The lectures are on MIT OpenCourseWare under CC BY-NC-SA 4.0. That licence is non-commercial and this course is sold, so it cites a lecture figure by lecture and slide, works it in its own panel and explains the idea in its own words. The PDFs are still published, and most of their printed figures agree with the engine at the precision printed.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 5, 'Which texts does the course quote word for word, each with its citation?', '["Every text in the source table, each with its edition.", "The ESD.260J lectures, whose slide titles the course copies as the headings of its lessons.", "Harris''s 1913 article, in its 1913 words only, and MIL-HDBK-338B (1 October 1998).", "Harris''s article as typeset in the 1990 reprint, since the reprint is the copy the course read."]'::jsonb, 2, 'Only public-domain texts are quoted: the 1913 words of Harris and the US Department of Defense handbook. The 1990 reprint''s typesetting is copyright ORSA, so only the 1913 words are used. The lectures are cited by lecture and slide, and no slide title or slide text is reproduced.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 6, 'Two well-known inventory textbooks are absent from the course''s source table. What does the course say about them?', '["They are not publicly readable, so they were not read and neither is cited.", "They were read, and their worked examples are the goldens the engine is checked against.", "They are cited by chapter for every formula, as the lectures are cited by slide number.", "They are quoted in the Expert tier, once the learner has bought the course''s reading pack."]'::jsonb, 0, 'The validation record says Silver, Pyke and Thomas and Nahmias are not publicly readable, so neither was read or cited. The engine''s published checks come from Harris, the MIT lectures and MIL-HDBK-338B. A text that was not read cannot be cited, by chapter or otherwise.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 7, 'What does the EK-11 materials and spares register of the Ekene field state about itself?', '["That it is a year of real Niger Delta stores records, with the part numbers changed so that no operator or supplier can be traced.", "That its eighteen items were chosen by an audit firm as a fair sample of an offshore store''s spend by value.", "That its prices are the list prices of named suppliers in 2026, converted to US$ at a stated exchange rate.", "That it is synthetic teaching data, written by a stated script, with no real company, person, supplier or price in it."]'::jsonb, 3, 'The register''s own label says it is SYNTHETIC teaching data for a fictional teaching field, and that no real company, person, supplier or price appears. It was written for this platform by a stated script. Its money is in US$, and every figure in it is a stated input a learner can read in the calculator''s box.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 8, 'Which ABC policy does the Ekene register state?', '["A to 70 percent and B to 90 percent of annual usage value, with the rule include-crossing.", "A to 80 percent of annual usage value and B to 95 percent, with the rule at-or-below.", "A to 80 percent of the items by count and B to 95 percent of them, with the rule at-or-below.", "None: the engine applies its own cut-offs whenever the register leaves them out of the call."]'::jsonb, 1, 'The Ekene policy states A to 80 percent, B to 95 percent, at-or-below, and the cut-offs are shares of annual usage value. The engine holds no cut-off of its own: a call without cut-offs is refused by name. Other figures would be another policy, and the course quotes every ABC class with the cut-offs and rule it came from.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 9, 'The engine exports 12 figures of its own in DEFAULTS. What are they?', '["A holding rate of 0.22, a rounding multiple of 10 and the Ekene bands, used for any call that leaves them unstated.", "The Ekene criticality weights and class minimums, kept so that a blank case always produces a class for every item.", "Its tie convention of 12 significant digits, the weight sum of 100 and how far weights may miss it, and caps on the size of a call.", "Twelve service targets, one for each month of the year, which the calculator reads when a learner types none."]'::jsonb, 2, 'DEFAULTS holds the tie convention, the weight sum and its tolerance, and caps such as 5000 items in one call and 20 criteria. None of them is a cost, a weight, a cut-off or a band. Every input a figure depends on is stated by the caller, and a call without one is refused by name.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 10, 'An EOQ call types the key holdingrate in lower case. What does the engine return?', '["The EOQ computed as if the holding rate were missing, with the misspelt key dropped silently and nothing said about it anywhere in the result, so the learner sees a figure and no sign that an input went unread.", "An EOQ on the holding rate the key was meant to be, since the engine matches keys without regard to their case.", "A result with a note under the reason that one key was unread, so that the learner can correct it on the next run.", "A refusal, in its own words: \"holdingrate is not an accepted key; the accepted keys at the top level are annualDemand, orderCost, holdingCostPerUnitYear, unitCost, holdingRate, rounding\"."]'::jsonb, 3, 'The engine refuses any key it does not read, at every level, naming the key, where it sits and the keys it accepts. A key dropped in silence would leave an input unstated with nobody told, and the engine does not guess what a misspelling meant.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 11, 'A box carries a key the function does not read and also lacks a required input. Which refusal comes back?', '["The unknown key, because every function checks its accepted keys before it reads any input.", "The missing input, since a required figure matters more.", "Both at once, listed in the order the fields appear in the box, so they can be fixed together.", "Neither: the engine repairs the spelling and computes the result, and the reason notes the repair."]'::jsonb, 0, 'Every function checks its accepted keys first, so the unknown key is refused before the missing input is reached. The engine returns one refusal at a time, and it repairs nothing on its own. Fix the key, run again, and the next refusal names the missing input.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 12, 'On the Ekene policy, CSG-958 scores 42.000000, below the E minimum of 44. What does the engine return for it?', '["A refusal naming items[10].scores, since a score that falls below a class minimum cannot be placed in any class.", "A result: class D, with a reason naming the minimum it reached and the E minimum it fell short of.", "A refusal naming classes, since the policy leaves a gap between the E and D minimums.", "A result with no class and a warning, since the item lies between two stated classes."]'::jsonb, 1, 'An item below a class minimum takes the next class down, with a reason: "CSG-958: weighted score 42 is at or above 0, the minimum for class D, and below 44 for class E". A result with a reason is a result. The last class starts at 0, so every item takes a class and there is no gap to refuse.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 13, 'In this course, what does the word EOQ name?', '["The quantity on the purchase order, whatever rounding the store applied on its way there.", "The quantity ordered plus the stock on hand, which is what the store holds after delivery.", "The nearest whole number to the square-root figure, since nobody orders part of a unit.", "The unrounded square-root figure; the quantity ordered is the one the stated rounding rule gives."]'::jsonb, 3, 'The vocabulary is binding: the EOQ is the unrounded square-root figure, 137.408584 for the Ekene baryte, and the quantity ordered is what the stated rule gives, 140.000000 rounded up to a multiple of 10. A rounding to a whole number is one stated rule among several, and it produces a quantity ordered.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 14, 'The Ekene register carries HEAT-TRC, a "Heat tracing controller (obsolete model)". When does this course call an item obsolete?', '["Whenever its name or the vendor says the model is out of production, whatever the store records.", "Once its stock would last over 24 months of usage.", "Only against a stated band: in the Ekene policy, 36 months or more since the last issue.", "After twelve months with no issue, a rule the engine applies to every register."]'::jsonb, 2, 'Obsolete, slow and excess are always of a stated band or a stated cover limit. HEAT-TRC is band obsolete because 40 months have passed since its last issue, at or above the band''s minimum of 36. More than 24 months of cover is the Ekene excess limit, a separate measure, and no band is built into the engine.'),
  ('materials', 'beginner', 'module', 'm01-materials-and-the-register', 15, 'What does the course say about where its practicals run and what is graded?', '["They run only in the Materials & Spares Planner, so a Suite seat is needed before a learner can attempt any exercise.", "They run in the course''s own calculator panels on the same vendored engine, and each graded number is a value that engine returns on fixed inputs.", "They run in a spreadsheet the course supplies, and grading compares the learner''s figure with the class average.", "They run in the panels, and the graded figures are sampled afresh for each learner so that no two answers match."]'::jsonb, 1, 'The register calculator calls the same vendored engine the lessons quote, and the Planner in the Suite gives the same figures on the same inputs, so no Suite seat is needed. Every graded number is an engine return on inputs written down in advance, with exactly one right answer, and this tier samples nothing.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 1, 'The Ekene policy weights safety 40, production 30, leadTime 20 and redundancy 10, with scores out of 5. GL-VALVE scores 2, 4, 3 and 3 on those criteria. What weighted score does the engine return?', '["60, the mean of its scores as a share of 5.", "58.000000, from contributions of 16, 24, 12 and 6.", "54.000000, the score the engine returns for the choke bean set CHK-BEAN.", "12, the plain sum of its four scores."]'::jsonb, 1, 'Each criterion contributes its weight times the score over the scale of 5: 40 x 2 / 5 = 16, 30 x 4 / 5 = 24, 20 x 3 / 5 = 12 and 10 x 3 / 5 = 6, which sum to 58.000000, class E. The mean of the scores as a share of 5 ignores the weights, the plain sum ignores both the weights and the scale, and 54.000000 belongs to CHK-BEAN, which scores 2 on lead time.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 2, 'PSV-KIT, the pressure safety valve repair kit, has a weighted score of 68.000000 on the Ekene policy. Which criticality class does the engine give it, and why?', '["E, because 68.000000 is at or above the E minimum of 44 and below the V minimum of 70, and the class follows the score.", "D, because its ABC class is C, and the engine lowers the criticality of low-value items.", "V, because 68.000000 rounds to 70 when the engine compares figures at 12 significant digits, and so meets the V minimum.", "V, because it scores the maximum 5 on safety and the policy names safety as its override criterion."]'::jsonb, 3, 'The engine''s reason reads "PSV-KIT: scores the maximum 5 on safety, which places an item in class V whatever its weighted score (68, class E by score alone)". E is what the score alone gives, before the override. The ABC class plays no part in criticality. Twelve significant digits separate 68 from 70 plainly; the tie convention only settles figures that agree to that many digits.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 3, 'On the Ekene policy, a learner types an empty list into the override criteria control and runs the criticality view again. What happens to PSV-KIT?', '["It becomes class E, and its weighted score stays 68.000000.", "The call is refused: the list may not be empty.", "It stays class V, because a safety item keeps the top class under any policy.", "It becomes class D, and its weighted score falls to 44.000000 as well."]'::jsonb, 0, 'An empty list is a stated policy with no override, which the engine accepts; only a list left out is refused. Without the override PSV-KIT takes the class its score gives: 68.000000 is at or above 44 and below 70, so E. The override changes the class only and leaves the weighted score as it was; nothing in the engine protects a safety item except a stated override.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 4, 'MECH-SEAL scores 70.000000 on the Ekene policy, exactly the V minimum. What class does the engine return, and on what footing?', '["E; a score sits in a class only once it is strictly above that class''s stated minimum, so 70 falls short of V.", "V; the policy''s override on safety fires for MECH-SEAL whenever its score is exactly 70.", "V; the engine''s stated choice is that a class minimum is met at or above it, and its reason says so.", "Neither: a score equal to a minimum is refused as ambiguous until the minimum is moved."]'::jsonb, 2, 'The engine''s reason reads "MECH-SEAL: weighted score 70 is at or above 70, the minimum for class V". Met at or above is the engine''s stated choice; a minimum met only strictly above it is the alternative a policy could state, and no graded figure in the course moves between the two. MECH-SEAL scores 3 on safety, so the override does not fire, and a score on a minimum is a result with a reason.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 5, 'A learner lowers the redundancy weight from 10 to 9 and runs the Ekene criticality view. What comes back?', '["The classes, with the four weights scaled up in proportion until they add to 100 again.", "A refusal, in the engine''s words: \"criteria weights must add to 100; they add to 99\".", "Classes computed with the missing point of weight added to safety, the largest criterion of the four.", "A result on a scale of 99, with a note that the weighted scores now run up to 99."]'::jsonb, 1, 'The weights are percentages that must add to 100, and weights that miss it are refused before any score is computed. The engine rescales nothing and moves no weight between criteria: a policy that does not add up is returned to its author to state again.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 6, 'Three criteria weighted 33.3, 33.3 and 33.4 each score 7 out of 10, and the V minimum is 70. The stored sum falls a hair below 70. Which class does the engine return?', '["V, since it compares figures at 12 significant digits, and at that precision the sum reads as 70.", "E, since the stored sum is below 70 and the engine compares the stored numbers exactly as held.", "The call is refused, since weights of 33.3, 33.3 and 33.4 do not add to exactly 100 when stored.", "V, since the engine rounds every weighted score to a whole number before it compares it."]'::jsonb, 0, 'The engine''s reason reads "T: weighted score 70 is at or above 70, the minimum for class V". Comparing at 12 significant digits is its stated tie convention; exact comparison of the stored doubles is the alternative, and the course grades nothing that turns on it. The weights add to 100, so they are accepted; only the weighted score falls a hair short. No weighted score is rounded to a whole number.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 7, 'What counts does the engine return for each class under the stated criticality policy on the Ekene register?', '["5 in V, 6 in E and 7 in D, with PSV-KIT counted in E by its score.", "6 in V, 7 in E and 5 in D, with CSG-958 and BARYTE lifted into E.", "6 in V, 6 in E and 6 in D, since the minimums are set to split the register evenly.", "6 in V, 5 in E and 7 in D, with PSV-KIT in V by its override."]'::jsonb, 3, 'The engine returns V 6, E 5, D 7. Counting PSV-KIT in E would ignore the safety override. CSG-958 scores 42.000000 and BARYTE 30.000000, both below the E minimum of 44, so both stay in D. The minimums are the stated policy and split the register however its scores fall.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 8, 'A stated case scores out of 10 with the override on criterion s. Item X scores 9 on s, one below the maximum. What does the engine return for X?', '["Class V, since a score within one point of the maximum is treated as the maximum.", "A refusal, since an override criterion must be scored at its maximum or at zero.", "The class its weighted score gives, E at 45, since the override fires at the maximum only.", "Class V at a weighted score raised to the V minimum, so the reason stays consistent."]'::jsonb, 2, 'The engine''s reason reads "X: weighted score 45 is at or above 40, the minimum for class E, and below 70 for class V". The override fires only on the maximum score; one below it does nothing. Any score from 0 to the scale is accepted on an override criterion, and the override never changes a weighted score.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 9, 'What does the course say about VED (vital, essential, desirable)?', '["It teaches VED from a licensed maintenance standard, whose criteria and weights the engine applies to every register it is handed.", "It names VED as one scheme of stated criticality classes, and the Ekene policy happens to label its classes V, E and D.", "It treats VED as the engine''s built-in scheme, used whenever a call leaves its criteria or class minimums unstated.", "It replaces VED with ABC, since the two schemes rank the same items in the same order once the costs are known."]'::jsonb, 1, 'No licensed maintenance or reliability standard was read, so criteria and weights are the user''s stated policy and VED is named only as one example. The engine holds no scheme: a call without criteria or classes is refused by name. Criticality and ABC answer different questions and rank the register differently: PSV-KIT is V and C, BARYTE D and A.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 10, 'On the Ekene policy, which criterion supplies 40.000000 of the wellhead master valve WH-MV''s weighted score of 86.000000?', '["Production, where WH-MV scores 4 at a weight of 30 and supplies the most.", "Lead time, which carries the most weight.", "Redundancy, since a valve with no installed backup is scored heaviest in the policy.", "Safety, where WH-MV scores the maximum 5 at a weight of 40."]'::jsonb, 3, 'A criterion contributes its weight times the score over the scale: 40 x 5 / 5 = 40.000000 for safety. Production supplies 24.000000, lead time 16.000000 and redundancy 6.000000. The Ekene policy weighs safety most heavily and redundancy least. WH-MV is V both on its score and through the override, since it scores the maximum on safety.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 11, 'A policy lists its classes as V from 70 and E from 40, and stops there. What does the engine return?', '["A refusal: \"classes[1].minScore must be 0 so that every item takes a class; got 40\".", "The classes, with any item below 40 left unclassified and listed on its own at the foot of the result.", "A third class added from 0 so that items scoring below 40 still take a class.", "Every item below 40 placed in E, the last class the policy stated."]'::jsonb, 0, 'The last class minimum must be 0, so that every item takes a class; a policy that leaves low scorers with nowhere to go is refused before any score is computed. The engine adds no class of its own and leaves no item unclassified.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 12, 'Under a policy whose scale is 10, a learner enters 11 as the first item''s score on criterion s. What comes back?', '["The item''s class, with the score of 11 capped at the scale of 10 before the weighted score is summed.", "The item''s class, with a weighted score above 100 that marks the item as more critical than any other.", "A refusal naming the field: \"items[0].scores.s must be a number from 0 to scoreMax 10; got 11\".", "A refusal naming scoreMax, since a scale of 10 is too small for the scores the policy uses."]'::jsonb, 2, 'Every score must lie from 0 to the stated scale, and a score outside it is refused on the item''s own field, with the value printed. The engine caps nothing, so a weighted score never passes 100. The scale itself is accepted; the refusal names the score that broke it.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 13, 'A policy leaves out the override list entirely, stating no topClassOnMaxScore at all. What does the engine return?', '["The classes with no override, since none was stated.", "Safety taken as the override, as in most policies.", "Every criterion made an override, so that any maximum forces the top class.", "A refusal: \"topClassOnMaxScore must be an array of criterion ids (empty for none)\"."]'::jsonb, 3, 'The override list must always be stated, even when it is empty. A list quietly assumed empty would drop a safety part to a lower class with nobody having chosen it, so the engine asks the author to decide. It picks no criterion on its own.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 14, 'A stated case names two override criteria, s and p. Item W scores the maximum 10 on p and has a weighted score of 50. What does the engine return for W?', '["Class E, since the override fires only when an item scores the maximum on every listed criterion.", "Class V, with a reason naming p as the criterion that forced it and its score of 50 kept in view.", "A refusal, since a policy may name one override criterion and this one names two of them.", "Class V, with the weighted score raised to 100 so that it agrees with the class it was given."]'::jsonb, 1, 'The engine''s reason reads "W: scores the maximum 10 on p, which places an item in class V whatever its weighted score (50, class E by score alone)". A maximum on any listed criterion fires the override, a policy may list more than one, and the weighted score is left as it was.'),
  ('materials', 'beginner', 'module', 'm02-criticality', 15, 'COMP-RP scores 66.000000 on the Ekene policy. How does the engine''s reason place it?', '["E, at or above the E minimum of 44 and 4 short of the V minimum of 70.", "V, since 66.000000 is within the tolerance the engine allows on a class minimum.", "D, since 66.000000 is below the V minimum and the engine drops such items two classes.", "E, at or above 44, with no mention of V since the reason names only the class reached."]'::jsonb, 0, 'The engine''s reason reads "COMP-RP: weighted score 66 is at or above 44, the minimum for class E, and below 70 for class V". Below the top class, a reason names both the minimum reached and the one missed, which shows how far the item sits from a change of class. The only tolerance is the 12-digit tie convention, and an item takes the highest class whose minimum it reaches.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 1, 'The Ekene casing CSG-958 has an annual usage of 240 joints at a unit cost of 1450, and 60 joints on hand. What annual usage value does ABC rank it by?', '["87000.000000, the stock on hand times the unit cost, which is the value sitting on the shelf.", "1450, the unit cost alone, since ABC ranks the dearest items first whatever their usage.", "348000.000000, the annual usage times the unit cost.", "370000.000000, the value of the ESP motor, which heads the ranking."]'::jsonb, 2, 'Annual usage value is annualUsage x unitCost: 240 x 1450 = 348000.000000, rank 2 on the register. The stock on hand times the unit cost is the stock value the slow-moving view reports, which measures a different thing. Ranking by unit cost alone would ignore how much of an item flows through the store. 370000.000000 is ESP-MTR''s value at rank 1.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 2, 'The total annual usage value of the Ekene register is 1580620.000000. What share of it does the ESP motor ESP-MTR carry?', '["23.408536 percent, its value of 370000.000000 over the total.", "45.425213 percent, the cumulative share once the casing is counted.", "22.016677 percent, the share the engine returns for CSG-958 at rank 2.", "33.333333 percent, the share of the items that class A holds."]'::jsonb, 0, 'An item''s share is its annual usage value over the total, in percent: 370000.000000 over 1580620.000000 is 23.408536. The cumulative share after rank 2 is 45.425213, and 22.016677 is the casing''s own share. 33.333333 is the share of the items that class A holds, a count that would treat a motor and an O-ring kit alike, which ABC exists to avoid.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 3, 'Class G cement CEM-G brings the cumulative share from 78.753907 to 83.536840 on the Ekene register, with A to 80 percent and B to 95. What class does it take under each boundary rule?', '["A under at-or-below, and B under include-crossing, the higher class in each case.", "B under both rules, since its cumulative share of 83.536840 is above 80 either way.", "A under both rules, since the share before it, 78.753907, is below 80 either way.", "B under at-or-below, and A under include-crossing, since each rule reads a different share."]'::jsonb, 3, 'Under at-or-below the cumulative share including the item decides: "CEM-G: cumulative share 83.53684% is at or below 95% and above 80%", so B. Under include-crossing the share before it decides: "CEM-G: cumulative share before it 78.753907% is below 80%", so A. Each rule reads a different share, which is why the item that crosses a cut-off is the one they disagree on.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 4, 'On the Ekene register, which items take a different ABC class under include-crossing from the class they take under at-or-below?', '["CEM-G only, the one item crossing 80 percent.", "CEM-G and LUBE-OIL, the two items whose cumulative shares cross a cut-off.", "Every item from rank 7 downward, since include-crossing moves each of them up a class.", "None: the rules differ only on an exact cut-off."]'::jsonb, 1, 'CEM-G crosses 80 percent and LUBE-OIL crosses 95 percent, from 94.197214 to 95.654870. Include-crossing places each crossing item in the higher class: CEM-G A, LUBE-OIL B. Every other item takes the same class under both rules. On a share exactly on a cut-off the two rules agree, because no item crosses a line there.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 5, 'Under the Ekene policy (A to 80, B to 95, at-or-below), how many items are class A, and what share of the annual usage value do they hold?', '["7 items, holding 83.536840 percent, the count under the other boundary rule.", "6 items, holding 80 percent exactly, since class A is filled up to its cut-off.", "6 items, holding 78.753907 percent, the share at GL-VALVE.", "3 items, holding 63.645911 percent, since class A closes at a third of the items."]'::jsonb, 2, 'Under at-or-below, class A is ranks 1 to 6, ending with GL-VALVE at a cumulative share of 78.753907. A cut-off is a ceiling for the cumulative share under this rule, so A holds what its items hold and need not reach 80. Seven items and 83.536840 are what include-crossing gives, with CEM-G joining A. The cut-offs are shares of value; no share of items closes a class.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 6, 'A stated case has items a and b with the same annual usage value of 10.000000. How does the engine order them, and on what footing?', '["a and b both at rank 1, since two items of equal value share a rank between them.", "b at rank 1 and a at rank 2, since a tie is ranked by id with the later id first.", "It refuses the case, since a tie in value leaves the cumulative share undefined.", "a at rank 1 and b at rank 2: the engine ranks ties by id ascending, a choice it states in its basis."]'::jsonb, 3, 'The basis reads "annual usage value = annualUsage x unitCost, ranked highest first (ties by id); the cumulative share including the item decides against A 80% and B 95%; compared at 12 significant digits" as it prints on the Ekene call. Ranking a tie by id ascending is the engine''s stated choice, and id descending is the alternative. No graded figure depends on it, and a tie in value is ranked with no refusal.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 7, 'A stated case has three items worth 80.000000, 15.000000 and 5.000000, so the cumulative shares land exactly on 80 and 95. Under at-or-below, what classes does the engine return?', '["A, B and C: a share exactly on a cut-off stays in the class that cut-off closes.", "B, C and C: a share on a cut-off has crossed it.", "A, A and B: the item on each cut-off is pulled into the higher class, as include-crossing does.", "A refusal: a share may not land on a cut-off."]'::jsonb, 0, 'The engine''s reasons read "P: cumulative share 80% is at or below 80%" and "Q: cumulative share 95% is at or below 95% and above 80%", so P is A, Q is B and R is C. Under include-crossing the same case gives the same classes, since the share before Q is exactly 80 and the share before R exactly 95. Nothing here is refused.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 8, 'A policy states A to 80 percent and B also to 80 percent. What does the engine return?', '["The classes, with class B empty, since no cumulative share can lie above 80 and at or below 80.", "A refusal: \"cutoffs.bPct must be a number above aPct 80 and below 100; got 80\".", "B moved up to 95 percent, the figure the engine holds for a missing B cut-off.", "A single class for A and B, merged at 80 percent."]'::jsonb, 1, 'The B cut-off must lie above the A cut-off and below 100, so a policy that leaves no room for class B is refused before any item is ranked. The engine holds no cut-off of its own and merges no classes; it returns the policy to its author to state again.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 9, 'A learner sets the boundary rule control to not stated in the ABC view. What does the engine print?', '["The classes under at-or-below, the rule most textbooks use, with a note that the rule was taken as read.", "Both rules side by side, so the learner can pick one after seeing the results printed.", "Crossing items left unclassed until a rule is stated, each flagged in its own reason.", "A refusal on boundaryRule, in a message that names both rules and what each one decides."]'::jsonb, 3, 'The engine holds no boundary rule: leaving it out is refused, in the engine''s words "boundaryRule must be ''at-or-below'' (the cumulative share including the item decides) or ''include-crossing'' (the share before the item decides, so the item crossing a cut-off joins the higher class)". It picks neither and prints no side-by-side result. Neither rule is right in general, so a policy picks one and writes it down.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 10, 'The engine''s basis for ABC cites Caplice, MIT ESD.260J (2006) lecture 11 slide 4. What does the course take from that citation about the cut-offs?', '["The lecture fixes A at 80 percent and B at 95 percent, and the engine applies those two figures to every register.", "A table of cut-offs by industry, printed in the lecture, whose oil and gas row the engine reads.", "The classes are arbitrary, so the cut-offs are the caller''s stated policy and the course states none as a standard.", "Cut-offs by item count, set in the lecture, which the engine converts to shares of value before it classifies."]'::jsonb, 2, 'The basis reads "Caplice, MIT ESD.260J (2006) lecture 11 slide 4 (standard ABC analysis; the classes are arbitrary, so the cut-offs are the caller''s stated policy)". The source supports ranking by value; where the lines fall is a decision the policy writes down. 80 and 95 are the Ekene policy''s choice, and the engine refuses a call that states no cut-offs.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 11, 'HEAT-TRC, the obsolete heat tracing controller, has an annual usage of 0 at a unit cost of 3100. How does the Ekene ABC run treat it?', '["It is refused, since an item with no annual usage value cannot be placed in the ranking.", "It is ranked last with a value of 0.000000 and a cumulative share of 100.000000, class C.", "It is ranked by its unit cost of 3100, since its usage of zero would otherwise hide it.", "It is left out of the ranking and listed apart, with a reason saying it holds no value."]'::jsonb, 1, 'An item may have zero value; it ranks at the foot of the register, 18th, and is class C under either rule. Only a register in which every item has zero value is refused: "items must carry some annual usage value; every annualUsage x unitCost is 0". The engine ranks by annual usage value alone and leaves no item out.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 12, 'PSV-KIT is criticality class V on the Ekene policy. Which ABC class does it take under the Ekene cut-offs and at-or-below?', '["C, since six kits a year at 3800 each carry a cumulative share of 97.097342.", "A, since every class V item is also ABC class A.", "B, since its safety score lifts its annual usage value by the override weight.", "V, since ABC reuses the criticality classes."]'::jsonb, 0, 'ABC weighs the money that flows through an item: PSV-KIT''s value of 22800.000000 ranks 13th and its cumulative share of 97.097342 is above 95, so it is C. Criticality weighs the consequence of a stockout and plays no part in ABC. The two classes answer two questions, which is why the course writes "criticality class V" and "ABC class C".'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 13, 'BARYTE is criticality class D on the Ekene policy. Where does it sit by annual usage value?', '["Rank 18, class C, since a class D item has the least consequence and carries no weight in ABC.", "Rank 5, class B, one below its ranking.", "Rank 1, class A, since bulk materials are always ranked ahead of spares by annual usage.", "Rank 5, class A, with a value of 78000.000000 from 300 tonnes a year at 260 each."]'::jsonb, 3, 'BARYTE''s annual usage value is 300 x 260 = 78000.000000, rank 5, with a cumulative share of 73.895054, at or below 80, so A. Criticality plays no part in the ranking. It ranks behind ESP-MTR, CSG-958, ESP-PMP and WH-MV on value, and nothing moves an item by its kind.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 14, 'What does the cumulative share of GL-VALVE, 78.753907, decide about GL-VALVE under the Ekene policy and at-or-below?', '["It is below 95, so GL-VALVE is class B.", "It is within two points of 80, so GL-VALVE is flagged for a boundary review.", "It is at or below 80, so GL-VALVE is class A, the last item in A.", "It sits near the cut-off, so GL-VALVE is class A only under include-crossing."]'::jsonb, 2, 'Under at-or-below the cumulative share including the item decides, and 78.753907 is at or below the A cut-off of 80, so GL-VALVE is A, at rank 6. The next item, CEM-G, carries the share past 80. B takes shares above 80 and at or below 95. The engine flags nothing near a cut-off, and compares shares at 12 significant digits with no rounding to whole numbers.'),
  ('materials', 'beginner', 'module', 'm03-abc-by-annual-usage-value', 15, 'How many Ekene items are class A under include-crossing, with the same cut-offs of 80 and 95?', '["7, since CEM-G joins A when the share before it decides.", "6, as under at-or-below.", "8, since include-crossing also lifts MECH-SEAL, the item after CEM-G.", "5, since include-crossing closes A as soon as the share before an item passes 70."]'::jsonb, 0, 'Under include-crossing ranks 1 to 7 are A: CEM-G''s share before it is 78.753907, below 80, so it joins A. MECH-SEAL''s share before it is 83.536840, at or above 80, so it is B. Six A items is the at-or-below count. The rule changes which share is read; the cut-offs stay 80 and 95.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 1, 'The Ekene baryte case states a demand of 300 tonnes a year, an order cost of 1800, a unit cost of 260 and a holding rate of 0.22. What EOQ does the engine return?', '["140.000000 tonnes, the figure that goes on the purchase order.", "274.817167 tonnes, the square root of 2 x 1800 x 300 over 57.2, doubled for the two costs.", "137.408584 tonnes, the square root of 2 x 1800 x 300 over 57.2.", "7859.770989 tonnes, the square root of 2 x 1800 x 300 x 57.2."]'::jsonb, 2, 'The EOQ is sqrt(2 A D / h) with h = 0.22 x 260 = 57.2: 137.408584. 140.000000 is the quantity ordered, rounded up to a multiple of 10. 274.817167 is the EOQ at four times the demand. The square root of 2 A D h is the relevant cost at the EOQ, 7859.770989 a year, which is money and has no unit of tonnes.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 2, 'The baryte holding cost is stated as a rate of 0.22 a year on a unit cost of 260. What holding cost of a unit for a year does the engine report?', '["57.200000, the holding rate times the unit cost.", "0.22, the rate itself, read as money a tonne a year.", "Half of 57.200000, since half a lot is held on average.", "78000.000000, the rate applied to the whole year''s purchase."]'::jsonb, 0, 'The engine reports holdingRate x unitCost = 0.22 x 260 = 57.200000 a tonne a year. Half a lot on average appears in the holding cost a year, h Q / 2, and it acts on h; it does not halve h itself. 78000.000000 is the purchase cost a year, 300 x 260, which the engine reports on its own line.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 3, 'Baryte is ordered 140 tonnes at a time against a demand of 300 a year and an order cost of 1800. What ordering cost a year does the engine report?', '["4004.000000, the holding cost a year at the same quantity ordered.", "3929.885495, the ordering cost the engine reports at the unrounded EOQ.", "1800, a single order a year.", "3857.142857, from 2.142857 orders a year at 1800 each."]'::jsonb, 3, 'The ordering cost a year is A D / Q = 1800 x 300 / 140 = 3857.142857, with D / Q = 2.142857 orders a year. 4004.000000 is the holding cost at 140, and 3929.885495 is each of the two equal costs at the EOQ itself. A lot of 140 tonnes covers less than half a year''s demand of 300.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 4, 'On the baryte case, what is the holding cost a year at the quantity ordered of 140 tonnes?', '["Twice 4004.000000, with the whole lot of 140 held all year long.", "4004.000000, from 57.2 x 140 / 2, with half a lot held on average.", "3857.142857, the ordering cost a year at the same quantity of 140.", "57.200000, the cost of holding one tonne for a year."]'::jsonb, 1, 'Stock arrives a lot at a time and runs down steadily, so on average half a lot sits on the shelf: h Q / 2 = 57.2 x 140 / 2 = 4004.000000. Charging the whole lot all year doubles it. 3857.142857 is the ordering cost at 140, and 57.200000 is h, the cost for one tonne.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 5, 'The rule the engine states includes "relevant cost at Q* = sqrt(2 A D h)". What is the relevant cost at the EOQ for baryte?', '["7861.142857 a year, the relevant cost the engine reports at the quantity ordered of 140 tonnes.", "7859.770989 plus the purchase cost of 78000.000000, a year.", "3929.885495 a year, the ordering cost alone at the EOQ, which the rule names.", "7859.770989 a year, the lowest ordering plus holding cost on these stated figures."]'::jsonb, 3, 'sqrt(2 x 1800 x 300 x 57.2) = 7859.770989, the sum of the two equal costs at the EOQ. 7861.142857 is the relevant cost at 140, a little higher. The purchase cost is paid whatever the lot size, so it moves no EOQ and the engine leaves it out of the relevant cost. 3929.885495 is only one of the two equal halves.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 6, 'With the rounding rule set to none, the baryte order is the EOQ itself. What do the engine''s ordering and holding costs a year show there?', '["Both are 3929.885495: at the EOQ the two costs are equal, and they sum to 7859.770989.", "The ordering cost is 3857.142857 and the holding cost 4004.000000, as at every quantity.", "The holding cost is twice the ordering cost, since h Q / 2 is taken on a full lot of 137.408584.", "Both are 7859.770989, since each cost equals the relevant cost at the EOQ in turn."]'::jsonb, 0, 'Setting A D / Q equal to h Q / 2 and solving for Q gives the EOQ, so at the EOQ the two costs are equal: 3929.885495 each, 7859.770989 together. 3857.142857 and 4004.000000 are the two costs at 140 tonnes, where they differ. Each cost is half the relevant cost at the EOQ.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 7, 'Baryte''s purchase cost is 78000.000000 a year. Why does the engine report it on its own line and leave it out of the relevant cost?', '["It is a sunk cost the moment the order is placed, so an EOQ call is refused when a price is stated.", "It is paid by the supplier on delivery, so it falls outside what the store''s own budget pays for in a year.", "It is paid whatever the lot size, so it moves no EOQ; it matters once the price depends on the lot.", "It is already inside the holding cost of 57.200000, so adding it again would count it twice."]'::jsonb, 2, 'Demand times unit cost, 300 x 260 = 78000.000000, is the same at any lot size, so it plays no part in choosing one. The relevant cost holds only the costs that move with the lot: ordering and holding. The holding rate acts on the unit cost to give h, which is a different figure from the year''s purchase.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 8, 'Harris (1913) prints: "it is of value to know that this consumption must increase four fold to warrant doubling the manufacturing quantities." What does the engine return for baryte with the demand raised from 300 to 1200 and the rule none?', '["An EOQ four times 137.408584, since the EOQ grows in step with demand.", "An EOQ of 274.817167, twice 137.408584, as the root of four is two.", "An EOQ of 137.408584 again, since the demand does not enter the EOQ at all.", "A refusal, since a demand above 1000 tonnes calls for a different rule."]'::jsonb, 1, 'The EOQ grows with the square root of demand, so four times the demand gives twice the lot: 274.817167. That is Harris''s four-fold sentence, which follows from his square root. The demand does enter the EOQ, under the root, and no demand above 0 is refused.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 9, 'Harris (1913) writes the lot as "the square root of (240MS divided by C)", with M the monthly movement, S the set-up cost and C the unit cost. Where does his 240 come from?', '["It folds together the twelve months of a year and his ten per cent a year for interest and depreciation.", "It is his count of working days in a year, over which the set-up cost is spread evenly.", "2 x 120, the hours of a two-week run on the machines of his day, over which the set-up cost S is charged.", "A conversion factor from dollars to cents, since his unit cost is printed in cents."]'::jsonb, 0, 'Harris''s 240 folds together the twelve months of a year and his ten per cent a year: 2 x 12 over 0.1 is 240. With an annual demand of 12 M and a holding rate of 0.1 it is the same formula the engine applies, sqrt(2 A D / h).'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 10, 'How does the course read Harris''s three 1913 examples as engine inputs?', '["Annual demand equal to his monthly movement, since he wrote his formula for a single month of use.", "Order cost of 240 times his set-up cost, and a holding rate of 1, to carry his constant directly.", "Annual demand 12 times his movement, and a holding rate of 0.22 taken from the Ekene baryte case.", "Annual demand 12 times his monthly movement, order cost his set-up cost, his unit cost, and a holding rate of 0.1."]'::jsonb, 3, 'The golden inputs read his figures as annual demand 12 M, order cost S, unit cost C and a holding rate of 0.1 for his ten per cent a year. Nothing else is assumed. The Ekene holding rate belongs to the baryte case alone.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 11, 'Harris prints his first lot as 2,190. What does the engine return on the course''s reading of his inputs, and how does the course treat the two figures?', '["Exactly 2,190; the engine matches the print, which is why this example anchors the EOQ module.", "2190.890230; the course keeps both, noting that Harris prints each of his lots a little short of the formula.", "2190.890230; the course replaces the print with the engine''s figure, since the print is a misprint.", "The nearest whole unit above 2,190; the engine rounds each lot, and Harris dropped the fraction."]'::jsonb, 1, 'The engine''s EOQ on harris-1913-example is 2190.890230. Harris prints 2,190, 6,850 and 48.5 for figures the engine gives as 2190.890230, 6856.626965 and 48.554321: each short of the formula. Printed alike is one thing and equal another, so the course keeps the engine''s figure to six decimals beside the print as printed. The rule none returns the EOQ unrounded.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 12, 'Lecture 8 slide 9 of Caplice, MIT ESD.260J (Fall 2006) states an order cost of 500, a demand of 2000 a year, a holding rate of 0.25 and a unit cost of 50. What does the engine return?', '["An EOQ of 400.000000, an ordering cost of 2500.000000 and a relevant cost of 2500.000000 in all.", "An EOQ of 200.000000, with ordering and holding costs of 2500.000000 each and a relevant cost of 5000.000000 together.", "An EOQ of 400.000000, ordering and holding costs of 2500.000000 each, a relevant cost of 5000.000000.", "An EOQ of 400.000000 and a relevant cost of 105000.000000 a year, once the purchase cost is added to it."]'::jsonb, 2, 'sqrt(2 x 500 x 2000 / (0.25 x 50)) = 400, and at the EOQ the ordering and holding costs are equal, 2500.000000 each, a relevant cost of 5000.000000. The slide''s printed figures agree with the engine exactly. The relevant cost is the sum of both costs and leaves out the purchase cost.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 13, 'A learner sets the Annual demand control to 0 on the baryte case. What does the engine print?', '["\"annualDemand must be a finite number above 0; got 0\"", "An EOQ of 0.000000 tonnes.", "An EOQ on the last demand typed, with a note that 0 was not accepted.", "A refusal naming orderCost."]'::jsonb, 0, 'A demand of 0 gives no reason to order, and the engine refuses it by name before any figure is computed. The refusal names the field that failed, annualDemand; the order cost is still stated. The engine keeps no earlier input and returns no figure of zero in place of a refusal.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 14, 'A learner clears the Unit cost control on the baryte case and leaves the Holding rate control as it was. What comes back?', '["An EOQ with a holding cost of 0.22 a unit a year, the rate read as a figure in money by the engine itself.", "An EOQ with the holding cost left out, so the lot grows until the order cost is spread very thin over the year.", "A refusal: \"holdingRate must be a finite number above 0; got 0\", since the rate has no price.", "A refusal: \"unitCost is required with holdingRate (the holding cost is holdingRate x unitCost)\"."]'::jsonb, 3, 'A holding rate is a fraction of the unit cost, so a rate with no unit cost gives no holding cost at all, and the engine refuses the pair by name. It never reads a rate as money. The holding rate itself is stated and above 0, so the refusal names unitCost.'),
  ('materials', 'beginner', 'module', 'm04-the-economic-order-quantity', 15, 'What does the engine''s basis cite as the source of its EOQ rule?', '["A licensed inventory textbook, by chapter and page, since the rule has no public-domain source.", "Harris (1913), Factory 10(2) pp. 135-136, 152, and Caplice, MIT ESD.260J (2006) lecture 7 and lecture 8 slide 3.", "The Ekene register''s note on the baryte order cost, which states the rule beside the case.", "MIL-HDBK-338B (1 October 1998) section 5.3.8, the handbook the course quotes for the square root."]'::jsonb, 1, 'The basis reads "Harris (1913), How Many Parts to Make at Once, Factory 10(2) pp. 135-136, 152; Caplice, MIT ESD.260J (2006) lecture 7 and lecture 8 slide 3". Harris''s 1913 words are public domain and quoted; the lectures are cited by lecture and slide. The textbooks were not read, the register''s note says what the order cost covers, and MIL-HDBK-338B is the course''s source for spares.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 1, 'The Ekene policy rounds baryte''s EOQ of 137.408584 up to a multiple of 10. What quantity is ordered, and what rounding penalty does the engine report?', '["130.000000 tonnes, at a penalty of 0.153633 percent, the multiple of 10 below the EOQ.", "137.408584 tonnes, since the penalty of rounding is charged only when it passes one percent.", "140.000000 tonnes, at a penalty of 0.017454 percent a year.", "140.000000 tonnes, with the penalty printed in money a year."]'::jsonb, 2, 'Up takes the next multiple at or above the EOQ: 140.000000, at a relevant cost of 7861.142857 against 7859.770989 at the EOQ, a penalty of 0.017454 percent. 130.000000 and 0.153633 are what the rule down gives. The engine always orders the rounded quantity the stated rule gives and always reports the penalty. The penalty is a percentage of the relevant cost at the EOQ, and the engine prints no penalty in money.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 2, 'On the same baryte case, what does the rule down to a multiple of 10 order, and at what relevant cost a year?', '["130.000000 tonnes, at a relevant cost of 7871.846154 and a penalty of 0.153633 percent.", "140.000000 tonnes, at 7861.142857, since down and up agree when the EOQ is so near a multiple.", "130.000000 tonnes, at 7859.770989, since rounding changes the lot and leaves the cost where it was.", "A refusal: rounding down leaves the store short."]'::jsonb, 0, 'Down takes the multiple at or below the EOQ, 130.000000. It sits further below the EOQ than 140 sits above it, so it costs more: 7871.846154 a year, a penalty of 0.153633 percent. 7859.770989 is the cost at the EOQ itself. Rounding down is refused only when it would order nothing.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 3, 'Rounding baryte up to a multiple of 50 orders 150.000000 tonnes, 12.591416 above the EOQ. What does the engine report, and what does it show?', '["A penalty that climbs a full percent for every tonne above the EOQ, in a steep rise.", "A penalty of 0.017454 percent, the same as the multiple of 10, since the rule up is the same rule.", "A refusal, since a multiple of 50 is more than a third of the EOQ and the order would overshoot it.", "A penalty of 0.384604 percent, 7890 a year against 7859.77: the relevant cost is flat near its minimum."]'::jsonb, 3, 'The engine''s reason reads "EOQ = sqrt(2 x 1800 x 300 / 57.2) = 137.408584; ordered as 150 (up to a multiple of 50), a relevant cost of 7890 a year against 7859.77 at the EOQ", a penalty of 0.384604 percent. An order 12.591416 units above the EOQ costs well under half a percent more a year. The multiple of 10 gives 0.017454. No multiple is refused for its size; only a rounding that orders nothing is.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 4, 'Of these four rules, which costs least above the EOQ on the baryte case, and at what penalty?', '["The rule up to a multiple of 10, which orders 140.000000 at 0.017454 percent, the Ekene policy.", "The nearest multiple of 1, which orders 137.000000 at a penalty of 0.000443 percent.", "Down to a multiple of 10, which orders 130.000000 at 0.153633 percent.", "Up to a multiple of 50, which orders 150.000000 at 0.384604 percent."]'::jsonb, 1, 'Of the stated rules the nearest multiple of 1 lands closest to 137.408584, at 137.000000, and costs 7859.805839 a year, a penalty of 0.000443 percent. The Ekene rule costs 0.017454, down to 10 costs 0.153633 and up to 50 costs 0.384604. The rule none costs nothing above the EOQ, since it orders the EOQ itself.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 5, 'The baryte EOQ of 137.408584 is rounded to the nearest multiple of 10. What does the engine order?', '["140.000000, the same quantity the Ekene rule up gives, at a penalty of 0.017454 percent.", "130.000000, since nearest rounds toward the lower multiple whenever the EOQ has a fraction.", "137.408584, since the rule nearest keeps any EOQ within half a multiple of a round figure.", "The midpoint of 130 and 140, which splits the two costs evenly."]'::jsonb, 0, 'Nearest takes the closer of the two multiples: 137.408584 is nearer 140 than 130, so the engine orders 140.000000, the same as the rule up, at the same cost of 7861.142857 and penalty of 0.017454. 137.408584 is above the midpoint between 130 and 140. The rule nearest always orders a multiple.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 6, 'Halfway between two multiples: an EOQ of exactly 50.000000 is rounded to the nearest multiple of 100. What quantity does the engine order, and on what footing?', '["0, since a quantity exactly halfway rounds down to the lower multiple under the rule nearest.", "50.000000, since an EOQ with no nearer multiple is ordered as it stands, unrounded.", "100.000000; the engine takes an exact half upward, a stated choice its reason names as halves upward.", "A refusal, since an EOQ exactly halfway between two multiples leaves the rule nearest with no way to decide."]'::jsonb, 2, 'The engine''s reason orders 100 and names the rule as the nearest multiple of 100 with the words halves upward in brackets. Halves upward is the engine''s stated reading; halves downward is the alternative; under it the rounding gives 0, which the engine refuses. No graded figure in the course depends on which is taken.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 7, 'An EOQ that is already a whole multiple, 20.000000, meets the rule up to a multiple of 4. What is ordered?', '["The next multiple of 4 above 20, since up always moves the EOQ to a multiple strictly above it.", "The multiple of 4 below 20, since a figure already on a multiple is taken down to the one below it.", "A refusal, since an EOQ that is already a whole multiple needs the rule none stated.", "20.000000, since up takes the next multiple at or above the EOQ and 20 already is one."]'::jsonb, 3, 'Up takes the next multiple at or above the EOQ, so an EOQ already on a multiple stays where it is: 20.000000. The engine reads the quotient 20 / 4 at 12 significant digits, finds it whole, and multiplies back. Nothing is refused here, and a rule up with no rounding to do is a result.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 8, 'Under the rule nearest multiple of 10, what does an EOQ of 15.811388 become?', '["10.000000, since the rule nearest takes the multiple at or below any EOQ that is not a whole multiple.", "20.000000, since 15.811388 lies past the midpoint of 10 and 20, so nearer 20.", "15.811388, since the rule nearest leaves an EOQ unrounded when both multiples are within 10 of it.", "16, the closest whole unit, since the rule nearest rounds to a unit before it applies the multiple."]'::jsonb, 1, 'Nearest takes the closer multiple: 15.811388 is past the midpoint of 10 and 20, so the engine orders 20.000000. Taking the multiple below is the rule down. The rule nearest always orders a multiple of the stated figure, and it works on the quotient over the multiple directly.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 9, 'On a stated case whose EOQ is 400, the rounding rule and multiple would order a quantity of 0. What does the engine print?', '["An order of 0.000000 with a relevant cost that grows without limit, since no order is ever placed.", "An order of the smallest multiple above 0, since a store must order something.", "\"rounding gives an order quantity of 0 from the EOQ 400; state a smaller multiple or another rule\"", "\"rounding.multiple must be a finite number above 0; got 0\", naming the multiple."]'::jsonb, 2, 'A rounding that orders nothing is refused by name before any cost is computed, and the message says what to do: pick a multiple the EOQ can reach, or a rule that rounds up. The engine substitutes no multiple of its own. The multiple itself is above 0, so the refusal names rounding and leaves rounding.multiple alone.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 10, 'The rounding rule none is stated together with a multiple of 10. What does the engine return?', '["A refusal: \"rounding.multiple must be left out when the rule is ''none''\".", "The EOQ unrounded, with the multiple of 10 ignored since the rule none takes none.", "A quantity rounded to the nearest multiple of 10, since a stated multiple outranks the rule.", "Up to 10, the Ekene rule."]'::jsonb, 0, 'The rule none takes no multiple, so a multiple stated beside it is a contradiction and the engine refuses it by name. It ignores no input it was given and picks no rule for itself. The Ekene rule is up to a multiple of 10, a stated input of the baryte case alone.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 11, 'The baryte case is run with its rounding left blank in the box. Which message comes back?', '["The EOQ with no rounding, since a rule that is not stated is read as the rule none by the engine.", "\"rounding must be a stated rounding rule { rule: ''none'' } or { rule: ''up'' | ''down'' | ''nearest'', multiple }\"", "A lot rounded to the nearest whole unit, as Harris rounded his stud to 49 in the year 1913.", "Up to a multiple of 10, the rule the Ekene register states for its baryte order."]'::jsonb, 1, 'The rounding rule is a stated input with no fallback, and leaving it out is refused with a message that spells out the shapes a rule can take. The engine takes neither the rule none nor any rule of Harris or of the Ekene register on its own.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 12, 'A stated case gives the holding cost directly as 4.5 a unit a year, with the rule down to a multiple of 25. What EOQ and purchase cost does the engine report with no unit cost stated?', '["An EOQ of 200.000000, and a purchase cost of 36000.000000 at the Ekene baryte price.", "A refusal: a unit cost is needed first.", "A purchase cost of 0.000000, with the EOQ rounded down.", "An EOQ of 200.000000, and a purchase cost of none, since no unit cost is stated."]'::jsonb, 3, 'A holding cost stated directly needs no unit cost, and the EOQ is 200.000000, already a multiple of 25. The purchase cost is reported as none without a unit cost; with a unit cost of 30 stated beside the holding cost, it is 36000.000000 and the EOQ is unchanged. Only a holding rate needs a unit cost. Rounding down leaves a figure already on a multiple where it is.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 13, 'Baryte''s holding rate is set to 0 in a stated probe. What does the engine print?', '["A refusal naming holdingRate: stock that costs nothing to hold has no EOQ.", "An EOQ that grows without limit, since stock that costs nothing to hold can be bought in any lot.", "An EOQ of 0.000000, since a holding cost of zero cancels the square root.", "\"unitCost must be a finite number above 0; got 0\", since the holding cost falls to zero."]'::jsonb, 0, 'The engine''s words are "holdingRate must be a finite number above 0; got 0". A rate of 0 would make holding free, so the engine refuses the rate by name. The refusal names the field that holds the zero, holdingRate; the unit cost of 260 is still stated and above 0.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 14, 'How does the engine express the rounding penalty it reports on every EOQ call?', '["As money a year: the relevant cost at the quantity ordered less the relevant cost at the EOQ.", "As a percentage of the purchase cost a year, so that it can be set beside the price of the item.", "As a percentage of the relevant cost at the EOQ, from the relevant costs at the quantity ordered and at the EOQ.", "As the number of units between the EOQ and the quantity ordered, in whichever direction it falls."]'::jsonb, 2, 'The engine reports the relevant cost at the quantity ordered and at the EOQ, and the gap between them as a percentage of the cost at the EOQ: 0.017454 percent for baryte ordered as 140. The purchase cost stays out of it, and the distance in units is not what it reports.'),
  ('materials', 'beginner', 'module', 'm05-rounding-and-the-flat-bottom', 15, 'Harris (1913) writes of his stud: "The correct quantity is 48.5 or, say, 49." What does the engine return for the stud with the stated rule nearest multiple of 1?', '["An order of 48.5 exactly, the lot Harris prints, since the engine rounds the EOQ to one decimal.", "An order of the whole unit below the EOQ, since the rule nearest drops any fraction of a unit, however large it is, before ordering.", "An order of 50.000000 from an EOQ of 48.554321, since nearest takes any fraction upward to 50.", "An order of 49.000000 from an EOQ of 48.554321, with both relevant costs 27.43 a year to the cent."]'::jsonb, 3, 'The engine''s reason reads "EOQ = sqrt(2 x 1.85 x 360 / 0.565) = 48.554321; ordered as 49 (the nearest multiple of 1 (halves upward)), a relevant cost of 27.43 a year against 27.43 at the EOQ". 48.554321 is past the midpoint, so the nearest whole unit is 49, the figure Harris states in words. The two costs agree to the cent, the flat bottom again.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 1, 'The wellhead master valve WH-MV holds 3 units at 42000 and has gone 14 months without an issue. Under the Ekene bands, what band and write-down does the engine return?', '["Band active, written down 0, since 14 months is below the very slow minimum of 24.", "Band slow, written down 25 percent of 126000.000000, which is 31500.000000.", "Band slow, written down 25 percent of the unit cost of 42000, a quarter of one unit.", "Band very slow, written down half of 126000.000000."]'::jsonb, 1, 'The engine''s reason reads "WH-MV: 14 months since the last issue is at or above 12, band slow (below 24), written down 25% of 126000 = 31500; cover 17.996401 months is at or below 24". The stock value is on hand times unit cost, 3 x 42000, and the write-down is the band''s percentage of it. An item takes the last band whose minimum it has reached, and 14 months reaches slow at 12 and falls short of very slow at 24.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 2, 'Class G cement CEM-G has gone exactly 12 months without an issue, the slow band''s minimum. What band does the engine return, and on what footing?', '["Active; a band minimum is reached only once the months are strictly above it, so an item at exactly 12 stays active.", "Slow, because its cover of 2.333333 months marks it as stock that has stopped moving.", "A refusal, since an item may not sit exactly on a band''s minimum without a stated tie rule.", "Slow, since the engine reads 12 months as reaching the slow minimum of 12, a choice it states in its basis."]'::jsonb, 3, 'The engine''s reason reads "CEM-G: 12 months since the last issue is at or above 12, band slow (below 24), written down 25% of 14700 = 3675; cover 2.333333 months is at or below 24". At or above is the engine''s stated reading; reached only strictly above is the alternative, which would keep CEM-G active, and no graded figure in the course moves between the two. Cover plays no part in the band.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 3, 'What total write-down does the engine return across the Ekene register under its stated bands?', '["97955.000000, against a total stock value of 903240.000000.", "66425.000000, the write-down of band slow alone, the largest of the four bands.", "903240.000000, since stock that has stopped moving is written off in full at the year end.", "15500.000000, the obsolete band alone, since only obsolete stock is written down."]'::jsonb, 0, 'The band totals are 0.000000 for active, 66425.000000 for slow, 16030.000000 for very slow and 15500.000000 for obsolete, which sum to 97955.000000. Each band writes down its own stated percentage, so slow and very slow stock is written down in part as well. 903240.000000 is the stock value of the whole register.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 4, 'HEAT-TRC, the heat tracing controller, holds 5 units at 3100, has gone 40 months without an issue and has a monthly usage of 0. What does the engine return for it?', '["A refusal naming items[16].monthlyUsage, since cover cannot be worked out with no usage at all.", "Band obsolete and written down in full, with no excess, since cover has no meaning without usage.", "Band obsolete, written down 100 percent, 15500.000000, with all 5.000000 units reported as excess.", "Band very slow, half its value written down, since 40 months falls inside that band''s range."]'::jsonb, 2, 'The engine''s reason reads "HEAT-TRC: 40 months since the last issue is at or above 36, band obsolete, written down 100% of 15500 = 15500; no usage, so all stock on hand is excess". A usage of 0 is accepted: cover has no meaning then, so all stock on hand is excess. That is a result with a reason. Very slow runs from 24 months to below 36, so 40 months is obsolete.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 5, 'The O-ring kit ORING-KIT holds 400 kits and uses 5 a month. With the Ekene excess limit of 24 months, what does the engine return for its cover and excess?', '["Cover of 80.000000 months and an excess of 400.000000, since all stock above the limit counts.", "Cover of 80.000000 months and an excess of 280.000000 kits above the 120 the limit allows.", "Cover of 20.000000 months, the months since its last issue, so it carries no excess at all.", "Cover of 80.000000 months and no excess, since band slow already writes its value down."]'::jsonb, 1, 'Cover is on hand over monthly usage: 400 / 5 = 80.000000 months, above 24, so the item carries excess. The limit allows 24 x 5 = 120 kits, and the excess is the stock above that, 280.000000. Months since the last issue sets the band; it is a separate measure from cover. The band''s write-down and the excess are reported side by side.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 6, 'The ring joint gasket GASKET-RJ holds 120 at 38, has gone 24 months without an issue and uses 4 a month. What does the engine return?', '["Band slow, a quarter of 4560.000000 written down, since 24 months is the top of the slow band.", "Band very slow, 2280.000000 written down, with 30.000000 months of cover and no excess, the limit being 30.", "Band obsolete, 4560.000000 written down, since 24 months with excess cover counts as obsolete.", "Band very slow, 2280.000000 written down, with 30.000000 months of cover and 24.000000 units of excess."]'::jsonb, 3, 'The engine''s reason reads "GASKET-RJ: 24 months since the last issue is at or above 24, band very slow (below 36), written down 50% of 4560 = 2280; cover 30 months is above 24, excess 24 units". 24 months reaches the very slow minimum. Cover is 120 / 4 = 30.000000, above the limit of 24, and the limit allows 24 months at 4 a month, so 24.000000 units are excess. Obsolete starts at 36 months whatever the cover.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 7, 'On the stated boundary items, COVER24 has exactly 24.000000 months of cover and COVER25 has 25.000000, against an excess limit of 24. What does the engine return?', '["COVER24 carries no excess, and COVER25 carries 1.000000 unit of excess.", "Both carry excess, since a cover limit is reached at or above it, like a band.", "Neither carries excess, since cover must pass the limit by a full month to count.", "COVER24 carries 1.000000 unit of excess, and COVER25 carries 2 units."]'::jsonb, 0, 'Stock is excess only strictly above the cover limit: 24.000000 months is inside it, and 25.000000 months is one month''s usage over it, 1.000000 unit. The engine states this in its basis as "excess above 24 months". It is the engine''s stated reading, with at or above the limit as the alternative. A band minimum works the other way: it is reached at or above it.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 8, 'On the stated boundary items, EMPTY has no stock on hand, no usage and 50 months since its last issue. What does the engine return for it?', '["A refusal, since an item with no stock and no usage has no place on a register.", "Band obsolete with all its stock excess, as for any item that has no usage at all.", "Band obsolete, with no excess, since there is no stock on hand to call excess.", "Band active, since an item holding nothing cannot be slow or obsolete."]'::jsonb, 2, 'EMPTY is 50 months since its last issue, at or above the obsolete minimum of 36, so its band is obsolete, with a stock value of 0.000000 and nothing written down. With no usage all stock on hand is excess, and it has none, so it carries no excess. The engine accepts a zero stock and a zero usage.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 9, 'A policy states its first band from 6 months. What does the engine print?', '["The bands, with any item below 6 months left unbanded and listed on its own.", "A refusal of the first band''s minimum, which has to start at 0 months.", "The bands, with an active band from 0 months added so that every item takes one.", "A refusal naming bands[1].minMonths, the second band, which starts at 12."]'::jsonb, 1, 'The engine''s words are "bands[0].minMonths must be 0 so that every item takes a band; got 6". Stock issued last month would otherwise fall below every band. The engine adds no band of its own. The refusal names the first band, whose minimum is the one that fails.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 10, 'A policy states a write-down of 101 percent for its first band. What does the engine return?', '["A refusal of the write-down, which the engine takes only as a percentage from 0 to 100.", "A write-down capped at 100 percent, the most any stock can lose on the books.", "A write-down of 101 percent, which carries a disposal cost beyond the stock value.", "A refusal naming bands[0].minMonths, since the first band must start at 0."]'::jsonb, 0, 'The engine''s words are "bands[0].writeDownPct must be a number from 0 to 100; got 101". The engine caps nothing and invents no disposal cost. The first band''s minimum is not what failed here, so the refusal names writeDownPct.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 11, 'In the slow-moving view, the Ekene cover limit of 24 months is replaced by 0. What comes back?', '["Every item with any stock at all reported as excess, since no cover is allowed.", "No item reported as excess, since a limit of 0 switches the excess test off.", "The Ekene limit of 24 months restored, with a note that 0 was not a limit.", "A refusal naming excessCoverMonths, the cover limit, which has to be above 0."]'::jsonb, 3, 'The engine''s words are "excessCoverMonths must be a finite number above 0; got 0". A limit of 0 is refused by name. The engine switches no test off and restores no earlier value; it names the field it would not accept.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 12, 'What does the engine return for band slow on the Ekene register: how many items, what stock value and what write-down?', '["3 items, a stock value of 126000.000000 and a write-down of 31500.000000.", "4 items, a stock value of 265700.000000 and half of it written down.", "4 items, a stock value of 265700.000000 and a write-down of 66425.000000.", "2 items, a stock value of 32060.000000 and a write-down of 16030.000000."]'::jsonb, 2, 'Band slow holds WH-MV, CSG-958, CEM-G and ORING-KIT: 126000 + 87000 + 14700 + 38000 = 265700.000000, written down 25 percent, 66425.000000. 126000.000000 and 31500.000000 are WH-MV alone. Two items, 32060.000000 and 16030.000000, are band very slow. The slow band''s percentage is 25, a quarter of its value.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 13, 'The casing CSG-958 is band slow at 13 months since its last issue, yet it holds only 3.000000 months of cover. What does the pair of figures show?', '["The register has an error, since an item with 3 months of cover must have been issued in the last month.", "The two measures ask two questions: whether an item is still issued, and whether the store holds more than it needs.", "The engine has put the casing in the wrong band, since cover below 24 months keeps an item active.", "The write-down should fall to 0, since the casing is not excess and only excess stock is written down."]'::jsonb, 1, 'Months since the last issue sets the band and its write-down; cover against the stated limit sets excess. They can disagree: the casing is band slow, written down 21750.000000, with 3.000000 months of cover and no excess, while the O-ring kit is band slow and carries excess. Cover plays no part in the band.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 14, 'What does the engine''s basis for slow-moving stock say about the bands, write-downs and cover limit?', '["They are the caller''s stated policy, and it cites lecture 13 slide 13 for days of supply to find dead stock.", "They are fixed by the lecture it cites, and the engine applies the same four bands to every register.", "They follow the accounting standard for inventory, which sets 25, 50 and 100 percent by age of stock.", "They come from the Ekene register, which the engine reads whenever a call leaves its bands unstated."]'::jsonb, 0, 'The basis reads "the bands, write-down percentages and cover limit are the caller''s stated policy; Caplice, MIT ESD.260J (2006) lecture 13 slide 13 (days of supply IOH / D to find dead stock)". The engine holds no write-down schedule, the course reads no accounting standard, and a call without bands is refused by name.'),
  ('materials', 'beginner', 'module', 'm06-slow-moving-and-obsolete-stock', 15, 'The first item in a slow-moving call has no months since its last issue in the box. What does the engine print?', '["The item placed in band active, since an item with no record is taken to be in use.", "Band obsolete, since no record of an issue means the item has never moved off the shelf at all.", "Nothing for that item: it is left out of the bands and the totals, with a note beside it.", "A refusal naming items[0].monthsSinceLastIssue, with the missing value printed as undefined."]'::jsonb, 3, 'Every item needs its months since the last issue. The engine''s words are "items[0].monthsSinceLastIssue must be a finite number at or above 0; got undefined". The engine places no item in a band it was not given the months for, and it drops nothing from the totals.'),
  ('materials', 'beginner', 'final', null, 1, 'ESP-PMP, the ESP pump section, scores 2 on safety, 5 on production, 5 on lead time and 4 on redundancy. Under the Ekene weights and a scale of 5, what is its weighted score and class?', '["82.000000, class V, the ESP motor''s figure.", "16, the plain sum of its scores.", "70.000000, class V, since a pump section is held at the V minimum.", "74.000000, class V, from contributions of 16, 30, 20 and 8."]'::jsonb, 3, '40 x 2 / 5 = 16, 30 x 5 / 5 = 30, 20 x 5 / 5 = 20 and 10 x 4 / 5 = 8 sum to 74.000000, at or above 70, so V: "ESP-PMP: weighted score 74 is at or above 70, the minimum for class V". 82.000000 belongs to ESP-MTR, one point higher on safety. The plain sum ignores the weights and the scale, and no item is held at a minimum by its kind.'),
  ('materials', 'beginner', 'final', null, 2, 'Which two Ekene items have a weighted score exactly equal to a class minimum of the stated policy?', '["PSV-KIT at 68.000000 and MECH-SEAL at 70.000000.", "MECH-SEAL at 70.000000 and GASKET-RJ at 44.000000.", "CSG-958 at 42.000000 and COMP-RP at 66.000000.", "GASKET-RJ at 44.000000 and HEAT-TRC at 24.000000."]'::jsonb, 1, 'The register plants MECH-SEAL exactly on the V minimum and GASKET-RJ exactly on the E minimum; each is in the class whose minimum it meets. PSV-KIT''s 68.000000 sits two below V, CSG-958 and COMP-RP sit below the minimums above them, and HEAT-TRC''s 24.000000 is well inside D.'),
  ('materials', 'beginner', 'final', null, 3, 'Two classes in a criticality policy are both labelled V, the first from 70 and the second from 0. What comes back?', '["Two V classes merged into one.", "The classes, with the second V renamed V2.", "Every item from 0 to 70 labelled V, with a note beside the repeat.", "A refusal on the second class: \"classes[1].label repeats the label ''V''\"."]'::jsonb, 3, 'A class label may be used once only, and a repeat is refused on the field that repeats it. The engine merges nothing and renames nothing; the policy''s author states the classes again.'),
  ('materials', 'beginner', 'final', null, 4, 'In a criticality call, the first two items share the id X. What does the engine print?', '["A refusal in the engine''s words: \"items[1].id repeats the id ''X''\"", "The classes, with the second X renamed so that both items appear in the result.", "Only the first X classed, the second dropped as a duplicate.", "One entry under X, with the two items'' scores averaged."]'::jsonb, 0, 'Every id in a call must be unique, and the engine refuses the repeat on the second item''s field. It renames, drops and averages nothing, since any of those would change the register without its owner deciding.'),
  ('materials', 'beginner', 'final', null, 5, 'A policy''s criteria have the ids s and p, and its override list names safety. What does the engine print?', '["No override at all, since safety is not a criterion here.", "The classes with s taken as the override.", "Every criterion taken as the override, to keep safety items safe.", "\"topClassOnMaxScore[0] must be a criterion id (s, p); got safety\""]'::jsonb, 3, 'Each id in the override list must be one of the policy''s own criteria, and the message lists them. The engine matches no id by its first letter and applies no override that was not stated.'),
  ('materials', 'beginner', 'final', null, 6, 'The first item in a criticality call carries a score under the key q, while the policy''s criteria are s and p. What comes back?', '["The class, with q ignored.", "The class, with q read as a third criterion of weight 0 in the weighted score.", "A refusal naming items[0].scores.s.", "A refusal: \"items[0].scores.q is not a criterion; the criteria are s, p\"."]'::jsonb, 3, 'An item may score only the stated criteria; a score under any other key is refused on the field that carries it, with the list of criteria. A criterion of weight 0 is refused in its own right, and the order of the scores in the box does not matter.'),
  ('materials', 'beginner', 'final', null, 7, 'The criterion key weight is typed as wieght in a criticality call. What does the engine print?', '["The classes, with the first criterion''s weight read from wieght, a close enough match to weight.", "A refusal saying the weights fall short of 100, since the first weight is missing.", "The classes, with the first criterion dropped and the other weights left as they were.", "\"criteria[0].wieght is not an accepted key; the accepted keys of criteria[0] are id, label, weight\""]'::jsonb, 3, 'The engine refuses a key it does not read at every level, naming the key, its path and the accepted keys of that object. It checks keys before it reads any input, so the misspelling is refused before any sum of weights is taken, and no key is matched by resemblance.'),
  ('materials', 'beginner', 'final', null, 8, 'What is the most criteria, and the most classes, one criticality call accepts?', '["4 criteria and 3 classes, as in the Ekene policy.", "100 criteria, one for each point of weight, and 5 classes, one for each score.", "20 criteria and 10 classes, two of the caps the engine holds in DEFAULTS.", "No limit on either."]'::jsonb, 2, 'DEFAULTS.MAX_CRITERIA is 20 and DEFAULTS.MAX_CLASSES is 10, and a call beyond either is refused by name with the cap in the message. The Ekene policy uses four criteria and three classes, well inside both caps.'),
  ('materials', 'beginner', 'final', null, 9, 'ESP-PMP is used 3 times a year at 96000 each. What annual usage value does ABC rank it by, and where does it rank?', '["192000.000000, the stock on hand at that price.", "96000, since ABC ranks by unit cost alone and it is the third dearest item.", "288000.000000, rank 3 on the Ekene register.", "288000.000000, rank 1, since its value is the largest of the pump and motor spares."]'::jsonb, 2, 'Annual usage value is 3 x 96000 = 288000.000000, behind ESP-MTR at 370000.000000 and CSG-958 at 348000.000000, so rank 3. 192000.000000 is its stock value, 2 on hand at 96000, which the slow-moving view reports. ABC ranks by annual usage value; unit cost alone ranks nothing.'),
  ('materials', 'beginner', 'final', null, 10, 'What class does the mechanical seal MECH-SEAL take in the Ekene ABC run, and does the boundary rule change it?', '["A under both rules, since it is criticality class V and carries the V weight.", "B under at-or-below and A under include-crossing, as the item that crosses 80.", "C under both rules, since its value of 53400.000000 is below the register''s mean.", "B under both rules, at a cumulative share of 86.915261."]'::jsonb, 3, 'MECH-SEAL ranks 8th: its share before it is 83.536840, above 80, and its cumulative share 86.915261 is at or below 95, so it is B under both rules. The item that crosses 80 is CEM-G, one rank above. Criticality plays no part in ABC, and no class is set against a mean.'),
  ('materials', 'beginner', 'final', null, 11, 'Class C is the largest group on the Ekene register by count under at-or-below. How much of the money does it carry?', '["5.802786 percent of the annual usage value, across 7 items.", "15.443307 percent, across 5 items, the share the middle class carries.", "78.753907 percent, across 6 items.", "5 percent exactly, since C is whatever share lies above the B cut-off of 95."]'::jsonb, 0, 'Class C is ranks 12 to 18 under at-or-below. The largest group by count carries the smallest share of the money, which is the pattern ABC is built to show. 5 items and 15.443307 describe class B, and 6 items and 78.753907 describe class A. C holds whatever its items hold; the B cut-off of 95 fixes no share for C.'),
  ('materials', 'beginner', 'final', null, 12, 'The surface safety valve actuator SSV-ACT brings the cumulative share to 94.197214. What does that decide under at-or-below and the Ekene cut-offs?', '["Class C, since a share within one point of 95 is read as having reached it.", "Class B: the share has passed 80 and has yet to pass 95, and SSV-ACT closes B.", "Class A, since only the B cut-off is read at this rank of the register.", "Class C, since every share above 80 falls outside class A and so into C."]'::jsonb, 1, 'SSV-ACT ranks 11th. Its cumulative share is above 80 and at or below 95, so it is B; the next item, LUBE-OIL, carries the share to 95.654870 and is C under at-or-below. The engine compares each share with both cut-offs at 12 significant digits.'),
  ('materials', 'beginner', 'final', null, 13, 'A policy states an A cut-off of 0 percent. What does the engine print?', '["It refuses cutoffs.aPct by name, since that cut-off has to lie above 0 and below 100.", "The classes with no A items at all.", "The classes with the A cut-off moved to 80, the figure lecture 11 slide 4 prints for it.", "\"cutoffs must be { aPct, bPct }, the cumulative value shares that close classes A and B\""]'::jsonb, 0, 'The engine''s words are "cutoffs.aPct must be a number above 0 and below 100; got 0". The message for cut-offs left out altogether is a different one. The engine holds no cut-off to fall back on, and the cited lecture supports ranking by value while the cut-offs are the caller''s policy.'),
  ('materials', 'beginner', 'final', null, 14, 'How does the engine rank items for ABC, and at what precision does it compare shares against the cut-offs?', '["By criticality class first and annual usage value second, compared to two decimals.", "By annual usage value, highest first, ties by id; shares compared at 12 significant digits.", "By unit cost, dearest first, ties by name; shares compared to the nearest whole percent.", "By annual usage alone, most used first, ties by the order in the box; compared exactly."]'::jsonb, 1, 'The engine ranks by annual usage value, highest first, and ranks a tie by id; it compares each cumulative share with the cut-offs at 12 significant digits. Both the id order and the 12-digit comparison are stated choices of the engine. Criticality plays no part in ABC, unit cost alone ranks nothing, and the order in the box decides no tie.'),
  ('materials', 'beginner', 'final', null, 15, 'With lots of 140.000000 tonnes, how often does the store reorder baryte, and how long does each lot last?', '["One order a year, a cycle of one year, since each lot is sized to the year.", "0.466667 orders a year, a cycle of 2.142857 years, each the other''s inverse.", "3 orders a year, a cycle of four months, since lots are placed quarterly.", "2.142857 orders a year, a cycle of 0.466667 years, from D / Q and Q / D."]'::jsonb, 3, 'Orders a year are D / Q = 300 / 140 = 2.142857, and the cycle is Q / D = 0.466667 years. The engine places no order on a calendar; the lot and the demand set the cycle.'),
  ('materials', 'beginner', 'final', null, 16, 'For the stud of his Figure III, Harris gives 48.5. Run with the rule none on his inputs, what EOQ comes out?', '["An EOQ of 48.5 exactly, which is why the stud is the check the course trusts most.", "An EOQ of 49.000000, Harris''s words.", "An EOQ of 48.554321, which Harris prints a little short of the formula.", "An EOQ of 2190.890230, since the stud and his first example share the same inputs."]'::jsonb, 2, 'The stud''s inputs, annual demand 360, set-up cost 1.85, unit cost 5.65 and a holding rate of 0.1, give 48.554321. Harris prints 48.5, short of it, as he prints his other lots. 49.000000 is what the engine orders under the stated rule nearest multiple of 1. 2190.890230 is his first example, on different inputs.'),
  ('materials', 'beginner', 'final', null, 17, 'The connector of Harris''s Figure II is read as an annual demand of 14760, an order cost of 2.15, a unit cost of 0.0135 and a holding rate of 0.1. What EOQ does the engine return, and what did Harris print?', '["6,850 from the engine; Harris printed 6856.626965.", "6856.626965 from the engine; Harris printed 6,850.", "6856.626965 from the engine, and Harris printed exactly the same figure.", "2190.890230 from the engine; Harris printed 2,190 for the connector."]'::jsonb, 1, 'On the course''s reading the connector''s EOQ is 6856.626965, and his article gives 6,850: his print falls short of the formula here too. A learner quotes the engine''s figure to six decimals and the print as printed. 2190.890230 and 2,190 belong to his first example, a different set of inputs.'),
  ('materials', 'beginner', 'final', null, 18, 'The baryte reason prints "a relevant cost of 7861.14 a year", while the panel''s field reads 7861.142857. Which figure does a learner reason with, and why do they differ?', '["The reason, 7861.14, since the field carries rounding noise from binary arithmetic.", "The field, 7861.142857; inside a message the engine prints money rounded to the cent.", "Either one, since two figures that print alike are equal for every purpose in the course.", "The field, since the reason''s figure is the relevant cost at the EOQ and the field is not."]'::jsonb, 1, 'Inside a message the engine prints money to the cent and a computed quantity to six decimals; the numeric field carries the figure at six decimals, and that is the one to reason with. Printed alike is not equal. Both figures are the relevant cost at the quantity ordered; the cost at the EOQ is 7859.770989.'),
  ('materials', 'beginner', 'final', null, 19, 'The Cost of an order control is set to -5. What does the engine do?', '["An EOQ on an order cost of 5, the sign dropped since a cost cannot be negative.", "It refuses orderCost, and the -5 is printed back exactly as it was typed.", "An EOQ of 0.000000, since a negative order cost makes every lot size free.", "\"annualDemand must be a finite number above 0; got -5\", naming the demand."]'::jsonb, 1, 'The engine''s words are "orderCost must be a finite number above 0; got -5". An order cost below zero has no meaning. It drops no sign and computes nothing on a policy that cannot work. The demand is stated and valid, so the refusal names orderCost.'),
  ('materials', 'beginner', 'final', null, 20, 'An EOQ call states neither a holding rate nor a holding cost a unit a year. What does the engine print?', '["\"unitCost is required with holdingRate (the holding cost is holdingRate x unitCost)\"", "An EOQ on a holding rate of 0.22, the rate the Ekene baryte case states.", "\"holdingCostPerUnitYear or holdingRate: state exactly one (holdingRate goes with unitCost)\"", "An EOQ that grows without limit, since holding stock costs nothing at all."]'::jsonb, 2, 'Neither form stated leaves nothing to hold against, and the engine refuses it with the same message it gives when both are stated: exactly one of the two forms is needed. It takes no rate from any register on its own. The unit cost message is for a rate stated without a price.'),
  ('materials', 'beginner', 'final', null, 21, 'Rounding up to a multiple of 0 is typed into the rounding controls. What happens?', '["The EOQ unrounded, read as rule none.", "\"rounding gives an order quantity of 0 from the EOQ 400; state a smaller multiple or another rule\"", "rounding.multiple is refused before any rounding is tried, with the 0 it got in the message.", "The EOQ rounded up to the next whole unit, since 0 is read as the smallest multiple there is."]'::jsonb, 2, 'The engine''s words are "rounding.multiple must be a finite number above 0; got 0". A multiple of 0 has no meaning. The message about an order of nothing is for a valid multiple the EOQ cannot reach. The engine reads no multiple as another rule.'),
  ('materials', 'beginner', 'final', null, 22, 'The baryte case lists every result the eoq function returns. Which of these is on that list?', '["The purchase cost a year, 78000.000000, reported beside the relevant cost and outside it.", "The count of spare lots to keep on the shelf between deliveries, from the stated demand.", "The net present value of a year''s orders, discounted at the stated holding rate.", "The supplier''s price break at which a larger lot would cost less per tonne."]'::jsonb, 0, 'The eoq function returns the EOQ, the quantity ordered, the holding cost of a unit for a year, orders a year, the cycle, the ordering, holding and relevant costs at the quantity ordered, the relevant cost at the EOQ, the rounding penalty and the purchase cost. It discounts nothing, prices no schedule and sets no stock target; stock targets belong to other functions, taught at the Professional tier.'),
  ('materials', 'beginner', 'final', null, 23, 'Why does a stated rounding rule cost baryte so little, whether up to 10 or even up to 50?', '["The engine charges no holding cost on the part of a lot above the EOQ, so a larger lot is nearly free.", "The penalty is set against the purchase cost of 78000.000000, which dwarfs any change in the lot.", "The relevant cost is flat near its minimum, so a lot some way from the EOQ adds only a small percentage.", "The engine rounds every relevant cost to the cent before it compares them, which hides the difference."]'::jsonb, 2, 'Near its minimum the relevant cost changes slowly with the lot size: 140 costs 0.017454 percent more a year and 150 costs 0.384604 percent more. The penalty is a percentage of the relevant cost at the EOQ, the purchase cost stays out of it, and the holding cost is h Q / 2, charged on the units held. Money is rounded to the cent only inside a message.'),
  ('materials', 'beginner', 'final', null, 24, 'What does the Ekene register''s note on the baryte case say the order cost of 1800 covers?', '["The purchase price of a tonne, the freight to the field and the insurance of the cargo while at sea.", "The storage of a lot at the shore base for the year, with its handling and rent.", "The purchase order, the marine freight booking and receiving at the Ekene shore base.", "The cost of running out between two orders, spread over the orders of a year."]'::jsonb, 2, 'The note reads "order cost covers the purchase order, the marine freight booking and receiving at the Ekene shore base". The price of a tonne is the unit cost, storage belongs in the holding cost, and a stockout cost is no part of the EOQ. Writing down what an order cost covers lets someone else check it.'),
  ('materials', 'beginner', 'final', null, 25, 'On the stated boundary items with the Ekene bands, AT12 has gone 12 months without an issue and BELOW12 has gone 11.99 months. What bands does the engine return?', '["AT12 is slow and BELOW12 is active, since a band is reached at or above its minimum.", "Both are slow, since 11.99 rounds to 12 at the engine''s precision.", "Both are active, since a band starts only after its minimum is passed.", "AT12 is active and BELOW12 is slow, since the bands count down from 36."]'::jsonb, 0, 'A band minimum is reached at or above it, the engine''s stated choice: 12 months reaches slow and 11.99 months does not. Twelve significant digits separate 11.99 from 12 plainly, so no tie arises. Bands count up from active at 0 months.'),
  ('materials', 'beginner', 'final', null, 26, 'ONEUNIT holds 13 units and uses 0.5 a month. It has reached 36 months without an issue, and its 26.000000 months of cover sits against a limit of 24. Band, write-down and excess?', '["Band obsolete, its whole stock value written down, and 1.000000 unit of excess.", "Band very slow, half its value written down, since 36 is the top of that band.", "Band obsolete, written down in full, and no excess, since obsolete stock is not counted.", "Band obsolete, and 26.000000 units of excess, one for each month of cover."]'::jsonb, 0, '36 months reaches the obsolete minimum, so the item is written down 100 percent of its stock value. Its cover of 26.000000 months is above 24, and the stock above 24 months of usage, 1.000000 unit, is excess. The band and the excess are reported side by side.'),
  ('materials', 'beginner', 'final', null, 27, 'The surface safety valve actuator SSV-ACT holds 1 unit at 27500 and has gone 26 months without an issue. What write-down does the engine return?', '["13750.000000: band very slow, 50 percent of 27500.000000.", "A quarter of the value, since 26 months is still inside band slow.", "27500.000000 in full, since any item past 24 months is obsolete.", "0.000000, since its cover is inside the limit."]'::jsonb, 0, 'The engine''s reason reads "SSV-ACT: 26 months since the last issue is at or above 24, band very slow (below 36), written down 50% of 27500 = 13750; cover 12.004802 months is at or below 24". Slow runs from 12 to below 24, obsolete starts at 36, and cover decides excess, which leaves the write-down alone.'),
  ('materials', 'beginner', 'final', null, 28, 'Band very slow holds just SSV-ACT and GASKET-RJ. What stock value and write-down does the engine print for it?', '["4 items, 265700.000000 of stock.", "32060.000000 held, with half of it, 16030.000000, written down.", "2 items, 32060.000000 of stock, all of it written down at the year end.", "1 item, 15500.000000 of stock, written down in full at 100 percent."]'::jsonb, 1, 'SSV-ACT and GASKET-RJ are band very slow: 27500 + 4560 = 32060.000000, written down 50 percent, 16030.000000. 4 items and 265700.000000 are band slow; one item at 15500.000000 is band obsolete.'),
  ('materials', 'beginner', 'final', null, 29, 'What does the engine return for the eleven Ekene items in band active?', '["A stock value of 903240.000000 and a write-down of 97955.000000.", "589980.000000 of stock value, with nothing at all written down.", "A stock value of 589980.000000 and a write-down of a quarter of it.", "No figures for active stock."]'::jsonb, 1, 'Band active is written down 0 percent in the Ekene policy, so its 11 items carry 589980.000000 of stock and nothing written down. 903240.000000 and 97955.000000 are the register''s totals. Every item in the call takes a band and appears in the totals.'),
  ('materials', 'beginner', 'final', null, 30, 'The pressure transmitter PT-XMTR holds 14 units and uses 0.8333 a month. What cover does the engine return, and is any of it excess?', '["9 months of cover, so no excess.", "16.800672 months of cover, which is excess, since any cover above 12 months counts.", "14 months of cover, one for each unit on hand, so 2 units above the band minimum.", "16.800672 months of cover, inside the limit of 24, so none of it is excess."]'::jsonb, 3, 'Cover is on hand over monthly usage: 14 / 0.8333 = 16.800672 months, at or below 24, so there is no excess. Nine months since its last issue sets its band, active. The cover limit is the stated 24 months, and a band minimum has nothing to do with excess.'),
  ('materials', 'beginner', 'final', null, 31, 'The ESP motor ESP-MTR holds 1 unit and uses 0.1667 a month. What cover does the engine return?', '["6 months exactly, since 0.1667 is one sixth of a unit a month.", "5.998800 months, inside the limit of 24, from 1 divided by 0.1667.", "7 months, the time since its last issue, which the engine reads as cover.", "0.1667 months, the usage itself, since it holds a single unit on hand."]'::jsonb, 1, 'Cover is 1 / 0.1667 = 5.998800 months. The usage is stated as 0.1667, and the engine divides by the figure as stated; it is close to one sixth and printed alike is not equal. Seven months since the last issue is a separate measure that sets its band, active.'),
  ('materials', 'beginner', 'final', null, 32, 'A policy states its bands from 0, then 24, then 12 months. Which message does the engine return?', '["The bands, sorted so 12 comes before 24.", "\"bands[0].minMonths must be 0 so that every item takes a band; got 6\"", "\"bands[2].minMonths must be above the band before it (24); got 12\"", "The bands, with the third band moved to 24 so that each starts above the last."]'::jsonb, 2, 'Each band must start above the one before it, and the engine refuses the first band that fails, naming the minimum it had to exceed. The first-band message is for a first band that starts above 0, and the engine moves and merges nothing.'),
  ('materials', 'beginner', 'final', null, 33, 'A slow-moving call names two bands with the same label a. What does the engine print?', '["The bands, with the second a renamed so that each label stays unique.", "Refused on the second band''s field: \"bands[1].label repeats the label ''a''\"", "The bands, with the two a bands merged into the first of them.", "A refusal in the engine''s words: \"bands must be an array of at least 1 band { label, minMonths, writeDownPct }\""]'::jsonb, 1, 'A band label may be used once only, and the repeat is refused on the second band''s field. The engine renames and merges nothing. The message about an array of bands is for a call with no bands at all.'),
  ('materials', 'beginner', 'final', null, 34, 'The first item in a slow-moving call has an on-hand figure of -1. What comes back?', '["The item''s band, with its stock value of -1 times its unit cost added into the totals.", "A band with 0 read as on hand.", "The figure is turned away on items[0].onHand, with the -1 echoed in the message.", "Its band, and a note that the register needs a stock count, printed beside it."]'::jsonb, 2, 'The engine''s words are "items[0].onHand must be a finite number at or above 0; got -1". Stock on hand below zero has no meaning. It reads no figure as another and adds nothing it refused to the totals.'),
  ('materials', 'beginner', 'final', null, 35, 'A register exported from another system gives each item a lastIssue field. What does slowMoving make of it?', '["The item banded on lastIssue read as its months since the last issue, the nearest key.", "The item banded with lastIssue ignored, and a refusal only if no months are stated.", "\"items[0].monthsSinceLastIssue must be a finite number at or above 0; got undefined\"", "A refusal of lastIssue by name, listing the six keys an item may carry."]'::jsonb, 3, 'The engine''s words are "items[0].lastIssue is not an accepted key; the accepted keys of items[0] are id, name, onHand, unitCost, monthsSinceLastIssue, monthlyUsage". It checks accepted keys at every level before it reads an input, and it would be refused first even with monthsSinceLastIssue missing as well. It reads no key as another and ignores no key.'),
  ('materials', 'beginner', 'final', null, 36, 'Which Ekene items carry excess stock under the stated cover limit of 24 months?', '["Two: ORING-KIT and GASKET-RJ, since HEAT-TRC has no usage and so no cover.", "Three: ORING-KIT, GASKET-RJ and HEAT-TRC.", "Four: the three in bands slow, very slow and obsolete that hold the most stock, and CSG-958.", "One: HEAT-TRC, the only item in band obsolete."]'::jsonb, 1, 'ORING-KIT has 80.000000 months of cover and GASKET-RJ 30.000000, both above 24; HEAT-TRC has no usage, so all its stock on hand is excess. CSG-958 is band slow with 3.000000 months of cover and no excess. Excess and band are separate measures.'),
  ('materials', 'beginner', 'final', null, 37, 'Where is the Materials & Spares Planner, and how do its figures relate to the course''s register calculator?', '["In the Suite''s Midstream & Downstream module; it vendors the same engine, so the same inputs give the same figures.", "In the Suite''s Drilling module; it runs its own engine, so a panel figure is checked against it by hand.", "In the academy itself, as a certificate reward; it adds figures the panels leave out for Suite learners.", "In the Suite''s Production module; it vendors an older engine, so small differences are expected there."]'::jsonb, 0, 'The Planner sits in the Suite''s Midstream & Downstream module and vendors this same engine. A figure worked in a panel and the same inputs typed into the Planner come from the same engine file, and every practical runs in the course''s own panels.'),
  ('materials', 'beginner', 'final', null, 38, 'Which of these does the engine take as a stated input, with nothing computed behind it?', '["The EOQ, read from the policy.", "The weighted score, which the policy states for each item in the register.", "The cumulative share, which the register carries for each item it ranks.", "The demand, with no forecast of it made anywhere in the engine."]'::jsonb, 3, 'The engine forecasts no demand: a demand is a stated input. It computes the EOQ from the stated costs, the weighted score from the stated scores and weights, and the cumulative share from the stated usages and costs.'),
  ('materials', 'beginner', 'final', null, 39, 'A question in this course touches tendering or discounting. Where does the course send the learner?', '["To the procurement course for tendering and bid evaluation, and to the cash flow course for discounting.", "Nowhere: the engine runs a tender and discounts each cost, and this course teaches both in module 4.", "To the Planner, which carries a tender module and a discounting module beside the stock views.", "To the lectures of ESD.260J, which the course quotes for both subjects in their own words."]'::jsonb, 0, 'The engine runs no tender and discounts no cost. The course names the procurement course for tendering, bid evaluation and contract types, and the cash flow course for discounting and NPV, in one sentence each, and teaches neither. The lectures are cited by lecture and slide and quoted nowhere.'),
  ('materials', 'beginner', 'final', null, 40, 'What does baryte''s EOQ of 137.408584 say, and what does it leave unsaid?', '["It is the tonnage the store will use in the next cycle, forecast from the stated demand of 300 a year.", "It is the lot the supplier has agreed to deliver, at the stated order cost of 1800 per order.", "It is the stock the store should hold at all times, above which baryte is reported as excess.", "It is the cheapest lot for the stated costs; it forecasts no demand and is no supplier''s promise."]'::jsonb, 3, 'An EOQ is the cheapest lot for the stated costs, and it is quoted with them. It is not a forecast of use, a supplier''s commitment or a stock level; excess is set by the stated cover limit in the slow-moving view.'),
  ('materials', 'beginner', 'final', null, 41, 'A register of many thousands of lines is sent to the ABC view in one call. Up to how many items will the engine take?', '["5000, the cap DEFAULTS.MAX_ITEMS sets.", "18, the size of the Ekene register.", "20, the same cap the criteria carry.", "No cap, since a register may hold any number of stock items."]'::jsonb, 0, 'DEFAULTS.MAX_ITEMS is 5000 for one criticality, ABC or slow-moving call. Twenty is the cap on criteria, and the Ekene register''s eighteen items sit far inside the cap. A call beyond the cap is refused by name.'),
  ('materials', 'beginner', 'final', null, 42, 'What does every result the engine returns carry beside its figures?', '["A confidence band on each figure, drawn from the canonical Monte Carlo on a fixed seed.", "A list of the inputs the engine filled in for itself, so the learner can review them.", "A basis block naming the rules applied and their sources, and a reason for each item or figure.", "A grade, from A to C, of how far the stated policy departs from an industry standard."]'::jsonb, 2, 'Every result carries a basis naming the rules and where they come from, and a reason on each item, band or candidate, so the working can be printed. The Associate functions sample nothing, the engine fills in no input, and no standard is read against which a policy could be graded.');
