-- ============================================================================
-- SC3 ASSOCIATE DEEP SEED: Materials, Spares & Inventory Management, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/materials/beginner.
--
-- What this tier owns: CRITICALITY, CLASSES AND THE ORDER QUANTITY. The
-- materials register and a stated policy for every figure; the texts with
-- their editions, licences and read dates; criteria, weights, the weighted
-- score, class minimums and the safety override; ABC by annual usage value
-- and the item that crosses a cut-off; the economic order quantity and its
-- cost at the optimum; the stated rounding rule and its cost; slow-moving and
-- obsolete stock, write-downs, cover and excess.
--
-- AN APP COURSE. The Suite app is the Materials & Spares Planner; the
-- practicals also run in the course's own register calculator. The capstone
-- grades six values of this tier, each identical under every reading the
-- engine states and never a Monte Carlo draw.
-- ============================================================================

values ('materials', 'beginner', '{"modules":[{"key":"m01-materials-and-the-register","title":"Materials and the Register","lesson_keys":["l01-why-a-materials-register","l02-sources-and-the-dates-they-were-read","l03-the-ekene-register-and-its-items","l04-a-stated-policy-for-every-figure","l05-calculator-panels-the-planner-and-refusals"]},{"key":"m02-criticality","title":"Criticality","lesson_keys":["l01-criteria-and-weights","l02-the-weighted-score","l03-classes-and-their-minimums","l04-the-safety-override"]},{"key":"m03-abc-by-annual-usage-value","title":"ABC by Annual Usage Value","lesson_keys":["l01-annual-usage-value","l02-ranking-and-the-cumulative-share","l03-the-item-that-crosses-a-cut-off","l04-criticality-and-abc-side-by-side"]},{"key":"m04-the-economic-order-quantity","title":"The Economic Order Quantity","lesson_keys":["l01-ordering-cost-and-holding-cost","l02-harris-and-the-lot-size","l03-the-square-root-formula","l04-the-relevant-cost-at-the-optimum","l05-three-lots-from-a-trade-magazine"]},{"key":"m05-rounding-and-the-flat-bottom","title":"Rounding and the Flat Bottom","lesson_keys":["l01-a-stated-rounding-rule","l02-the-cost-of-rounding","l03-halves-upward","l04-holding-cost-as-a-rate-or-a-figure"]},{"key":"m06-slow-moving-and-obsolete-stock","title":"Slow-Moving and Obsolete Stock","lesson_keys":["l01-months-since-the-last-issue","l02-bands-and-write-downs","l03-cover-and-excess","l04-the-capstone-brief"]}]}'::jsonb, 1)
